callGraph.callee:
buildFlowLayout({
      plan,
      selectedNodeId,
      graphCopy,
      onSelect: handleSelectNode,
    }).then

[
      section.startPoint,
      ...(section.bendPoints ?? []),
      section.endPoint,
    ]
      .map((point) => ({
        x: point.x - minLeft + LAYOUT_PADDING,
        y: point.y - minTop + LAYOUT_PADDING,
      }))
      .filter

input.plan.edges
    .flatMap<LayoutLink>((edge) => {
      const { from, to } = edgeEndpoints(edge);
      return from && to
        ? [
            {
              id: edge.id,
              source: from,
              target: to,
              weight:
                edge.emphasis === "inactive" || edge.active === false ? 1 : 2,
            },
          ]
        : [];
    })
    .sort

(() => {
        const statusCard = input.attention ?? input.readiness;
        return {
          title: statusCard.title,
          description: statusCard.description,
          statusLabel: statusCard.statusLabel,
          tone: normalizeTone(statusCard.tone),
          icon: input.attention ? ("warning" as const) : ("sparkles" as const),
        };
      })
